return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T13:56:07+00:00','po-revision-date'=>'2026-09-26T13:56:07+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'बहुभाषी WordPress, प्रत्येक भाषा के लिए एक पोस्ट: पोस्ट, पेजों, श्रेणियों, मीडिया टेक्स्ट, विजेट और साइट शीर्षक के आपके पुराने Tranzly अनुवादों के साथ लिंक किए गए अनुवाद।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI प्रदाता','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT के निर्माता। एक अच्छा ऑल-राउउंडर।','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude के निर्माता। लेखन और सावधानीपूर्वक तर्क करने में मजबूत।','Google\'s Gemini models. Fast and inexpensive.'=>'Google के Gemini मॉडल। तेज़ और किफायती।','A European AI company with fast, inexpensive models.'=>'एक यूरोपीय एआई कंपनी जो तेज़ और किफायती मॉडल प्रदान करती है।','Low-cost models that are good at writing and code.'=>'कम लागत वाले मॉडल जो लेखन और कोडिंग में अच्छे हैं।','One key for models from many different providers.'=>'कई अलग-अलग प्रदाताओं के मॉडलों के लिए एक ही कुंजी।','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'कोई भी सेवा जो OpenAI के API की तरह काम करती है, जिसमें आपके अपने कंप्यूटर या सर्वर पर चलने वाला मॉडल भी शामिल है।','General (used when nothing more specific is set)'=>'सामान्य (जब कोई अधिक विशिष्ट विकल्प सेट न हो)','Writing and rewriting'=>'लिखना और दोबारा लिखना','Translation'=>'अनुवाद','Code and CSS'=>'कोड और सीएसएस','Sorry, you are not allowed to access this page.'=>'क्षमा करें, आपको इस पृष्ठ तक पहुँचने की अनुमति नहीं है।','These settings are shared by every plugin that uses them: %s.'=>'ये सेटिंग्स उन सभी प्लगइन्स द्वारा साझा की जाती हैं जो इनका उपयोग करते हैं: %s।','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'आपकी कुंजियाँ इस साइट के डेटाबेस में एन्क्रिप्टेड हैं और केवल आपके द्वारा चुने गए प्रदाता को भेजी जाती हैं — हमें कभी नहीं।','Step 1 of 2: choose an AI provider'=>'चरण 1 का 2: एक AI प्रदाता चुनें','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'आप अपनी खुद की कुंजी लाते हैं, इसलिए आप अपने उपयोग के अनुसार प्रदाता को सीधे भुगतान करते हैं। सुनिश्चित नहीं हैं? इनमें से कोई भी ठीक काम करता है; आप बाद में और जोड़ सकते हैं।','Next'=>'अगला','Step 2 of 2: connect %s'=>'चरण 2 का 2: %s कनेक्ट करें','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'अपने OpenAI-compatible सेवा का पता दर्ज करें, जो /v1 पर समाप्त होता है। कुंजी (key) की आवश्यकता केवल तभी होती है जब सेवा इसके लिए कहती है।','Open %s and sign in (or create a free account).'=>'%s खोलें और साइन इन करें (या एक निःशुल्क खाता बनाएं)।','the %s API keys page'=>'%s एपीआई कुंजियाँ पृष्ठ','Create a new key and copy it.'=>'एक नई कुंजी बनाएं और इसे कॉपी करें।','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'इसे नीचे पेस्ट करें और "Save and test" दबाएं। यह काम करता है यह जांचने के लिए हम एक छोटी सी अनुरोध भेजते हैं।','Most providers need a little credit on the account before a key works: %s.'=>'अधिकतर प्रदाताओं को कुंजी काम करने से पहले खाते में थोड़ी क्रेडिट की आवश्यकता होती है: %s।','add credit'=>'क्रेडिट जोड़ें','← Choose a different provider'=>'← दूसरा प्रदाता चुनें','Address'=>'पता','Saved key ends in …%s — paste a new one to replace it'=>'सहेजी गई कुंजी का अंत …%s पर होता है — इसे बदलने के लिए एक नई कुंजी पेस्ट करें','Key (optional)'=>'कुंजी (वैकल्पिक)','API key'=>'API कुंजी','Save and test'=>'सहेजें और परीक्षण करें','Providers'=>'प्रदत्तकर्ता','Provider'=>'प्रदाता','Status'=>'स्थिति','Key'=>'कुंजी','Get a key'=>'कुंजी प्राप्त करें','Test'=>'परीक्षण','Remove'=>'हटाएँ','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'एक नए प्लगइन संस्करण द्वारा सहेजा गया: इस प्लगइन को अपडेट करें, या कुंजी को फिर से दर्ज करें।','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'सहेजी गई कुंजी को अब खोला नहीं जा सकता (साइट की सुरक्षा कुंजियाँ बदल गई हैं)। इसे फिर से दर्ज करें।','Not connected'=>'कनेक्टेड नहीं है','Connected — last test passed %s'=>'कनेक्टेड — अंतिम परीक्षण पास हुआ %s','Last test failed: %s'=>'पिछला परीक्षण विफल रहा: %s','Connected — not tested yet'=>'कनेक्टेड — अभी तक परीक्षण नहीं किया गया है','Which model to use'=>'कौन सा मॉडल उपयोग करना है','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ उस कार्य के लिए हमारी अनुशंसा को चिह्नित करता है। सूची में आपके की द्वारा उपयोग किए जाने वाले सभी मॉडल शामिल हैं, जिन्हें प्रदाता से लाइव पढ़ा जाता है।','— Recommended for the provider —'=>'— प्रदाता के लिए अनुशंसित —','Save models'=>'मॉडल सहेजें','Refresh the model lists from the providers'=>'प्रवाiders से मॉडल सूचियों को रीफ़्रेश करें','best quality'=>'सर्वश्रेष्ठ गुणवत्ता','lowest cost'=>'सबसे कम लागत','fastest'=>'सबसे तेज़','Add a model yourself'=>'स्वयं एक मॉडल जोड़ें','A model came out today? Paste its exact name to use it straight away.'=>'आज कोई नया मॉडल आया है? इसका तुरंत उपयोग करने के लिए इसका सटीक नाम पेस्ट करें।','Model name'=>'मॉडल का नाम','Add model'=>'मॉडल जोड़ें','Recommended models list'=>'अनुशंसित मॉडल सूची','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'अनुशंसित मॉडल सूची की पुष्टि नहीं की जा सकी, इसलिए कोई अनुशंसा नहीं दिखाई जा रही है। प्लग-इन को पुनः स्थापित करें, या नीचे दैनिक अपडेट चालू करें।','The list in use was published on %s. Each plugin update brings a fresh one.'=>'उपयोग में ली जाने वाली सूची %s को प्रकाशित की गई थी। प्रत्येक प्लगइन अपडेट एक नया सेट लाता है।','Also check Zinn Digital® once a day for an updated list.'=>'अद्यतन सूची के लिए दिन में एक बार Zinn Digital® की भी जाँच करें।','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'केवल एक सादा डाउनलोड अनुरोध भेजा जाता है: कोई कुंजी नहीं, कोई साइट पता नहीं, आपकी सामग्री के बारे में कुछ भी नहीं। सूची पर हस्ताक्षर किए जाते हैं, और हस्ताक्षर जाँच में विफल रहने वाली सूची को अनदेखा कर दिया जाता है।','Last checked %1$s: %2$s.'=>'अंतिम बार जाँच की गई %1$s: %2$s।','Save, and check now if turned on'=>'सहेजें, और चालू होने पर अभी जाँच करें','a newer list was installed'=>'एक नई सूची स्थापित की गई थी','already up to date'=>'पहले से ही अपडेटेड है','the download failed the signature check and was ignored'=>'डाउनलोड ने हस्ताक्षर जाँच को विफल कर दिया और उसे अनदेखा कर दिया गया','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® तक पहुँचा नहीं जा सका; वर्तमान सूची उपयोग में बनी रहेगी','turned off'=>'बंद है','Open'=>'खोलें','Check their status page'=>'उनका स्टेटस पेज देखें','Open your billing page'=>'अपना बिलिंग पेज खोलें','Open your API keys page'=>'अपने API कुंजियाँ पृष्ठ को खोलें','Open the AI settings'=>'एआई सेटिंग्स खोलें','Sorry, you are not allowed to do that.'=>'क्षमा करें, आपको ऐसा करने की अनुमति नहीं है।','Unknown provider.'=>'अज्ञात प्रदाता।','Enter the address of your service, for example http://localhost:11434/v1.'=>'अपने सेवा का पता दर्ज करें, उदाहरण के लिए http://localhost:11434/v1।','That does not look like an API key. Copy it again, without spaces.'=>'वह एपीआई कुंजी जैसी नहीं लगती। इसे बिना किसी रिक्त स्थान के दोबारा कॉपी करें।','Paste your API key first.'=>'पहले अपनी API की जोड़ें।','Key removed.'=>'कुंजी हटा दी गई।','Models saved.'=>'मॉडल सहेजे गए।','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'मॉडल का सटीक नाम दर्ज करें, उदाहरण के लिए जैसा कि प्रदाता के दस्तावेज़ीकरण में लिखा गया है।','Added %s. Choose it under "Which model to use".'=>'%s जोड़ा गया। इसे "कौन सा मॉडल उपयोग करें" के अंतर्गत चुनें।','Model removed.'=>'मॉडल हटाया गया।','Daily updates are off. The list that came with the plugin is used.'=>'दैनिक अपडेट बंद हैं। प्लगइन के साथ आई सूची का उपयोग किया जाता है।','Checked: %s.'=>'जाँच की गई: %s।','Model lists refreshed.'=>'मॉडल सूचियाँ ताज़ा की गईं।','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'आपकी एआई कुंजी आपके किसी प्लगइन के नए संस्करण द्वारा सहेजी गई थी। इस प्लगइन को अपडेट करें, या एआई सेटिंग्स में कुंजी को दोबारा दर्ज करें।','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'आपकी सहेजी गई AI कुंजी अब नहीं खोली जा सकती (साइट की सुरक्षा कुंजियाँ बदल गई हैं)। AI सेटिंग्स में इसे फिर से दर्ज करें।','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI सेट अप नहीं है। AI सेटिंग्स में किसी AI प्रदाता की कुंजी जोड़ें।','No model is chosen for this task. Pick one in the AI settings.'=>'इस कार्य के लिए कोई मॉडल नहीं चुना गया है। AI सेटिंग में एक मॉडल चुनें।','That AI provider is not supported by this version of the plugin.'=>'प्लगइन का यह संस्करण उस एआई प्रदाता का समर्थन नहीं करता है।','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'यह साइट आपकी AI सेवा तक नहीं पहुँच सकी। जाँच करें कि यह चल रही है और इसका पता आपके वेब सर्वर से पहुँचा जा सकता है (आपके अपने कंप्यूटर पर मौजूद सेवा होस्ट की गई साइट से नहीं पहुँच योग्य है)।','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'यह साइट %s तक नहीं पहुँच सकी। उनका स्टेटस पेज देखें; यदि वे काम कर रहे हैं, तो आपका होस्ट आउटगोइंग कनेक्शन को ब्लॉक कर रहा हो सकता है, या पता गलत है।','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s का कहना है कि आपके खाते में कोई क्रेडिट या कोटा शेष नहीं है। उनके साथ अपने खाते में क्रेडिट जोड़ें या अपनी सीमा बढ़ाएं, फिर पुनः प्रयास करें।','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ने आपकी कुंजी स्वीकार नहीं की। यह गलत टाइप की गई, निरस्त की गई या समाप्त हो चुकी हो सकती है। एक नई कुंजी बनाएँ और उसे यहाँ पेस्ट करें।','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ने आपकी कुंजी के लिए इस अनुरोध को अस्वीकार कर दिया। हो सकता है कि कुंजी को इस मॉडल या सुविधा तक पहुँच न प्राप्त हो, या आपके खाते को सत्यापित किए जाने की आवश्यकता हो।','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'मॉडल "%1$s", आपकी कुंजी के लिए %2$s से उपलब्ध नहीं है। AI सेटिंग्स में कोई अन्य मॉडल चुनें।','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'आपके %2$s प्लान में "%1$s" मॉडल शामिल नहीं है। AI सेटिंग्स में कोई दूसरा मॉडल चुनें या उनके साथ अपना प्लान अपग्रेड करें।','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s आपकी कुंजी द्वारा अनुरोध भेजने की गति को सीमित कर रहा है। एक मिनट प्रतीक्षा करें और पुनः प्रयास करें, या उनके साथ अपनी दर सीमा बढ़ाएँ।','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s में अभी समस्या आ रही है (उनकी ओर से आउटेज या ओवरलोड)। आपकी सेटिंग में कोई खराबी नहीं है। थोड़ी देर बाद पुनः प्रयास करें।','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'AI अनुरोध एक ऐसे कारण से विफल हो गया जिसकी हम पहचान नहीं कर सके। पुनः प्रयास करें; यदि यह समस्या बनी रहती है, तो नीचे दिए गए विवरण के साथ सहायता टीम से संपर्क करें।','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI प्रदाता ने ऐसे रूप में उत्तर दिया जिसे यह प्लगइन पढ़ नहीं सका। पुनः प्रयास करें; यदि ऐसा बार-बार हो, तो दूसरा मॉडल चुनें या सहायता टीम से संपर्क करें।','Custom (OpenAI-compatible)'=>'कस्टम (OpenAI-compatible)','Save a key for this provider first.'=>'पहले इस प्रदाता के लिए एक कुंजी सहेजें।','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'आपकी कुंजी काम करती है, लेकिन प्रदाता इसके लिए किसी टेक्स्ट मॉडल की सूची नहीं देता है। नीचे स्वयं एक मॉडल जोड़ें।','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'कनेक्टेड। %1$s ने %2$s का उपयोग करके उत्तर दिया। आपकी AI सुविधाएँ उपयोग के लिए तैयार हैं।','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'आपकी उपयोगकर्ता भूमिका को इस साइट पर AI का उपयोग करने की अनुमति नहीं है। किसी प्रशासक से संपर्क करें।','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'इस साइट ने अपनी मासिक AI खर्च सीमा पार कर ली है। एक प्रशासक इसे AI सेटिंग्स में बढ़ा सकता है।','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'यह साइट एआई अनुरोधों की अपनी मासिक सीमा तक पहुँच गई है। एक प्रशासक इसे एआई सेटिंग्स में बढ़ा सकता है।','Usage and cost'=>'उपयोग और लागत','The log, limits and role permissions apply to AI used through: %s.'=>'लॉग, सीमाएं और भूमिका अनुमतियां %s के माध्यम से उपयोग किए जाने वाले AI पर लागू होती हैं।','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'लागत अनुमानित है, जिसे प्रकाशित मूल्यों के आधार पर निकाला गया है; बिना ज्ञात मूल्य वाले मॉडल को शून्य माना जाता है।','This month: %1$s requests, about %2$s.'=>'इस महीने: %1$s अनुरोध, लगभग %2$s।','When'=>'जब','Who'=>'कौन','Used for'=>'इसके लिए प्रयुक्त','Model'=>'मॉडल','Tokens in / out'=>'इनपुट / आउटपुट टोकन','About'=>'के बारे में','Result'=>'परिणाम','No AI requests have been made yet.'=>'अभी तक कोई एआई अनुरोध नहीं किया गया है।','Done'=>'पूर्ण','Limits and permissions'=>'सीमाएँ और अनुमतियाँ','Monthly spending limit (US dollars)'=>'मासिक खर्च सीमा (US डॉलर)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'कोई सीमा न होने के लिए खाली छोड़ दें। अनुमानित लागत पहुँचने पर AI महीने के शेष भाग के लिए रुक जाता है।','Monthly request limit'=>'मासिक अनुरोध सीमा','Leave empty for no limit.'=>'कोई सीमा न रखने के लिए खाली छोड़ें।','Who may use AI'=>'AI का उपयोग कौन कर सकता है','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'किसी को भी न चुनें ताकि प्लगइन की सुविधाओं का उपयोग करने वाला हर कोई एआई (AI) का उपयोग कर सके। एडमिनिस्ट्रेटर हमेशा इसका उपयोग कर सकते हैं।','Save limits and permissions'=>'सीमाएँ और अनुमतियाँ सहेजें','Limits and permissions saved.'=>'सीमाएँ और अनुमतियाँ सहेजी गईं।','That language is not one of this site\'s languages.'=>'वह भाषा इस साइट की भाषाओं में से एक नहीं है।','A translation must be the same kind of content as the original.'=>'एक अनुवाद मूल सामग्री के ही प्रकार का होना चाहिए।','Choose one of the site\'s other languages.'=>'साइट की अन्य भाषाओं में से एक चुनें।','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'प्लगइन की इस कॉपी से एडमिन स्क्रीन की स्क्रिप्ट्स गायब हैं। इसे किसी रिलीज़ किए गए पैकेज से पुनः स्थापित करें।','This screen needs JavaScript.'=>'इस स्क्रीन के लिए जावास्क्रिप्ट की आवश्यकता है।','Choose a language'=>'भाषा चुनें','Upgrade'=>'अपग्रेड करें','Pricing'=>'मूल्य निर्धारण','Start Trial'=>'ट्रायल शुरू करें','Account'=>'खाता','Contact Us'=>'संपर्क करें','Affiliation'=>'संबद्धता','the kind of softwarePlugin'=>'प्लगइन','greetingHey %s,'=>'नमस्ते %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'सुरक्षा और फ़ीचर अपडेट, शैक्षिक सामग्री, और कभी-कभार मिलने वाले ऑफ़र के लिए ईमेल सूचनाएँ प्राप्त करने के लिए ऑप्ट-इन करें, और कुछ बुनियादी WordPress पर्यावरण जानकारी साझा करें। इससे हमें %s को आपकी साइट के साथ अधिक संगत बनाने और आपकी आवश्यकता के अनुसार बेहतर ढंग से काम करने में मदद मिलेगी।','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'सुरक्षा और फ़ीचर अपडेट, शैक्षणिक सामग्री, और कभी-कभार मिलने वाले ऑफ़र के लिए ईमेल सूचनाएं प्राप्त करने, और WordPress परिवेश संबंधी कुछ बुनियादी जानकारी साझा करने के लिए सहमति दें।','If you skip this, that\'s okay! %1$s will still work just fine.'=>'यदि आप इसे छोड़ देते हैं, तो कोई बात नहीं! %1$s फिर भी ठीक से काम करता रहेगा।','Allow & Continue'=>'अनुमति दें और जारी रखें','verbSkip'=>'छोड़ें','Skipping, please wait'=>'छोड़ रहे हैं, कृपया प्रतीक्षा करें','Continue'=>'जारी रखें','Please wait'=>'कृपया प्रतीक्षा करें','as activating pluginActivating'=>'सक्रिय किया जा रहा है','This will allow %s to'=>'इससे %s को अनुमति मिलेगी','Privacy Policy'=>'गोपनीयता नीति','Terms of Service'=>'सेवा की शर्तें','License Agreement'=>'लाइसेंस समझौता','Have a license key?'=>'लाइसेंस की है?','Activate License'=>'लाइसेंस सक्रिय करें','View Basic Profile Info'=>'बुनियादी प्रोफ़ाइल जानकारी देखें','Your WordPress user\'s: first & last name, and email address'=>'आपके WordPress उपयोगकर्ता का: पहला और अंतिम नाम, और ईमेल पता','View Basic Website Info'=>'बुनियादी वेबसाइट जानकारी देखें','Homepage URL & title, WP & PHP versions, and site language'=>'होमपेज यूआरएल और शीर्षक, WP और PHP संस्करण, और साइट की भाषा','View Basic %s Info'=>'बुनियादी %s जानकारी देखें','Current %s & SDK versions, and if active or uninstalled'=>'वर्तमान %s और SDK संस्करण, और क्या यह सक्रिय है या अनइंस्टॉल किया गया है','Newsletter'=>'न्यूज़लेटर','Updates, announcements, marketing, no spam'=>'अपडेट, घोषणाएं, मार्केटिंग, कोई स्पैम नहीं','View Diagnostic Info'=>'डायग्नोस्टिक जानकारी देखें','WordPress & PHP versions, site language & title'=>'WordPress और PHP संस्करण, साइट भाषा और शीर्षक','View Plugins & Themes List'=>'प्लगइन्स और थीम की सूची देखें','Names, slugs, versions, and if active or not'=>'नाम, स्लग, संस्करण, और सक्रिय हैं या नहीं','optional'=>'वैकल्पिक','Never miss an important update'=>'कभी भी कोई महत्वपूर्ण अपडेट न चूकें','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'हमने यह ऑप्ट-इन इसलिए पेश किया है ताकि आप कोई भी महत्वपूर्ण अपडेट न चूकें और %s को आपकी साइट के साथ अधिक संगत बनाने तथा आपकी ज़रूरतों के अनुसार बेहतर ढंग से काम करने में हमारी मदद कर सकें।','Thank you for updating to %1$s v%2$s!'=>'%1$s v%2$s पर अपडेट करने के लिए धन्यवाद!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'उपसर्ग 1 से 8 छोटे अक्षरों (lowercase) या अंकों का होना चाहिए, एक अक्षर से शुरू होना चाहिए, और प्लगइन का नाम नहीं होना चाहिए।','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" एक भाषा कोड नहीं है। fr_FR या de_DE जैसे WordPress लोकेल का उपयोग करें।','List at least one language.'=>'कम से कम एक भाषा सूचीबद्ध करें।','You are not allowed to translate this item.'=>'आपको इस आइटम का अनुवाद करने की अनुमति नहीं है।','This item already has a version in that language.'=>'इस आइटम का उस भाषा में पहले से ही एक संस्करण मौजूद है।','The value for %s is not one of the allowed choices.'=>'%s के लिए मान स्वीकृत विकल्पों में से एक नहीं है।','This item\'s group already has a %1$s version (#%2$d).'=>'इस आइटम के समूह में पहले से ही %1$s संस्करण (#%2$d) मौजूद है।','An item cannot be its own translation.'=>'एक वस्तु स्वयं अपनी अनुवाद नहीं हो सकती।','That item is already a translation of something else. Unlink it first.'=>'वह आइटम पहले से ही किसी अन्य चीज़ का अनुवाद है। पहले उसे अनलिंक करें।','The translation link could not be saved.'=>'अनुवाद लिंक सहेजा नहीं जा सका।','That text cannot be translated here.'=>'उस पाठ का यहाँ अनुवाद नहीं किया जा सकता।','That media text cannot be translated here.'=>'वह मीडिया टेक्स्ट यहाँ अनुवादित नहीं किया जा सकता है।','A translation can be published or kept as a draft.'=>'एक अनुवाद को प्रकाशित किया जा सकता है या ड्राफ्ट के रूप में रखा जा सकता है।','You are not allowed to publish this kind of content.'=>'आपको इस तरह की सामग्री प्रकाशित करने की अनुमति नहीं है।','This item is already written in that language.'=>'यह आइटम पहले से ही उस भाषा में लिखा गया है।','You are not allowed to change that translation.'=>'आपको वह अनुवाद बदलने की अनुमति नहीं है।','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'यह अनुवाद किसी व्यक्ति द्वारा संपादित (या आयात) किया गया था, इसलिए यह सुरक्षित है। इसे दोबारा अनुवाद करने के लिए अनलॉक करें।','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'अभी तक कोई अनुवाद इंजन सेट अप नहीं किया गया है। Tranzly → Engines में इसके लिए एक कुंजी जोड़ें।','That translation engine is not available on this site.'=>'वह अनुवाद इंजन इस साइट पर उपलब्ध नहीं है।','That translation engine is not set up yet: add its key first.'=>'वह अनुवाद इंजन अभी सेट अप नहीं किया गया है: पहले उसकी कुंजी (key) जोड़ें।','%s did not return a translation for every part of this item. Nothing was changed.'=>'%s ने इस आइटम के हर हिस्से के लिए अनुवाद नहीं लौटाया। कुछ भी बदला नहीं गया।','An engine id must be lowercase letters, digits and hyphens.'=>'एक इंजन आईडी में छोटे अक्षर, अंक और हाइफ़न होने चाहिए।','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Zinn Digital® Ltd के सीईओ Neil Lock द्वारा निर्मित','Version %s'=>'संस्करण %s','Tranzly website'=>'Tranzly वेबसाइट','Zinn Digital® website'=>'Zinn Digital® वेबसाइट','Settings saved.'=>'सेटिंग्स सहेजी गईं।','See the Pro plans and pricing'=>'प्रो प्लान और मूल्य निर्धारण देखें','Languages'=>'भाषाएँ','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'पहली भाषा वह है जिसमें आपकी सामग्री लिखी गई है। आगंतुक भाषा स्विचर ब्लॉक की मदद से भाषा बदलते हैं।','(default)'=>'(डिफ़ॉल्ट)','Locale code'=>'लोकेल कोड','For example fr_FR'=>'उदाहरण के लिए fr_FR','Name (optional)'=>'नाम (वैकल्पिक)','For example Français'=>'उदाहरण के लिए Français','Add language'=>'भाषा जोड़ें','Front-end output'=>'फ्रंट-एंड आउटपुट','Class name prefix'=>'क्लास नेम प्रीफिक्स','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'प्लगइन आपके पृष्ठों पर जो भी क्लास नाम प्रिंट करता है, वह इस उपसर्ग से शुरू होता है, ताकि पृष्ठों से यह पता न चले कि उन्हें किस प्लगइन ने बनाया है। 1 से 8 छोटे अक्षर या अंक, जो एक अक्षर से शुरू होते हैं।','Beta updates'=>'बीटा अपडेट','This site receives beta versions as updates.'=>'यह साइट अपडेट के रूप में बीटा वर्शन प्राप्त करती है।','This site receives stable versions only.'=>'यह साइट केवल स्थिर संस्करण प्राप्त करती है।','Change this on the Account page'=>'इसे खाता पृष्ठ पर बदलें','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'बीटा वर्ज़न उन लाइसेंस प्राप्त प्रो इंस्टॉलेशन के लिए उपलब्ध हैं जो उनके खाते से जुड़े हैं। एक बार कनेक्ट होने के बाद, आप अकाउंट पेज से शामिल हो सकते हैं।','Save settings'=>'सेटिंग्स सहेजें','Add a second language under 